import * as Crypto_Ed25519 from "./Crypto_Ed25519.js";
import * as Crypto_ECDSA from "./Crypto_ECDSA.js";
import * as Crypto_Schnorr from "./Crypto_Schnorr.js";
import { fromPrivateKeyDisplay } from "./KeyPair.js";
import { fromMnemonicDisplay, isMnemonicDisplay } from "./Mnemonic.js";
const cryptos = {
    Ed25519: Crypto_Ed25519,
    ECDSA: Crypto_ECDSA,
    Schnorr: Crypto_Schnorr
};
export const isPublicKeyByCryptoName = (name, value) => {
    return cryptos[name].isPublicKey(value);
};
export const displayPublicKeyByCryptoName = (name, publicKey) => {
    return cryptos[name].displayPublicKey(publicKey);
};
export const isPublicKeyDisplayByCryptoName = (name, value) => {
    return cryptos[name].isPublicKeyDisplay(value);
};
export const isPrivateKeyByCryptoName = (name, value) => {
    return cryptos[name].isPrivateKey(value);
};
export const displayPrivateKeyByCryptoName = (name, privateKey) => {
    return cryptos[name].displayPrivateKey(privateKey);
};
export const isPrivateKeyDisplayByCryptoName = (name, value) => {
    return cryptos[name].isPrivateKeyDisplay(value);
};
export const isPrimaryKeyByCryptoName = (name, value) => {
    return cryptos[name].isPrimaryKey(value);
};
export const appendCryptoIndexToPrimaryChars = (name, primaryChars) => {
    return cryptos[name].appendCryptoIndexToPrimaryChars(primaryChars);
};
export const publicKeyToPrimaryKey = (name, publicKey) => {
    return cryptos[name].publicKeyToPrimaryKey(publicKey);
};
export const primaryKeyToPublicKeyForCrypto = (name, primaryKey) => {
    return cryptos[name].primaryKeyToPublicKey(primaryKey);
};
export const splitPrimaryKeyAndCryptoIndex = (name, primaryKey) => {
    return cryptos[name].splitPrimaryKeyAndCryptoIndex(primaryKey);
};
export const isSignatureByCryptoName = (name, value) => {
    return cryptos[name].isSignature(value);
};
export const displaySignatureByCryptoName = (name, signature) => {
    return cryptos[name].displaySignature(signature);
};
export const isSignatureDisplayByCryptoName = (name, value) => {
    return cryptos[name].isSignatureDisplay(value);
};
export const sign = async (name, hash, privateKey) => {
    return await cryptos[name].sign(hash, privateKey);
};
export const verify = async (name, hash, signature, publicKey) => {
    return await cryptos[name].verify(hash, signature, publicKey);
};
export const generateKeyPair = async (name, length, mnemonicPassphrase) => {
    return await cryptos[name].generateKeyPair(length, mnemonicPassphrase);
};
export const keyPairFromPrivateKey = (name, privateKeyDisplay) => {
    const privateKey = isPrivateKeyDisplayByCryptoName(name, privateKeyDisplay) ? fromPrivateKeyDisplay(privateKeyDisplay) : privateKeyDisplay;
    return cryptos[name].keyPairFromPrivateKey(privateKey);
};
export const keyPairFromMnemonic = (name, mnemonicDisplay, mnemonicPassphrase) => {
    const mnemonic = isMnemonicDisplay(mnemonicDisplay) ? fromMnemonicDisplay(mnemonicDisplay) : mnemonicDisplay;
    return cryptos[name].keyPairFromMnemonic(mnemonic, mnemonicPassphrase);
};
export const derivePublicKeyFromXPub = (name, xpub, index) => {
    return cryptos[name].derivePublicKeyFromXPub(xpub, index);
};
